def _parse_ports(value):
    """按端口标记解析：普通面 n 占一个字符，其余端口标记占两个字符。"""
    value = "" if pd.isna(value) else str(value).strip()
    ports = []
    index = 0
    while index < len(value):
        if value[index] == "n":
            ports.append("n")
            index += 1
        else:
            ports.append(value[index:index + 2])
            index += 2
    return ports

