def _build_legend(device_ports):
    """只为当前设备实际出现的端口生成图例，未知端口保留特殊标记。"""
    legend = []
    seen = set()
    for mark in device_ports:
        if mark == "n" or mark in seen:
            continue
        seen.add(mark)
        legend.append((mark, _port_info(mark)["meaning"]))
    return legend

